#!/usr/bin/env bash
# In-repo copy for tests/spec_runner.rs (unit U0, 2026-10-14). Source: the review package,
# local/spec/tutorial/run-spec-demo.sh. Changes from the source are marked U0-EDIT. Run through
# `cargo test --test spec_runner`, or scripts/behaviour-lock.sh spec to compare two binaries.
# evnx spec demo runner (SP0-SP10). Non-interactive, safe: each scene runs in its own temp folder.
# Usage: EVNX=/path/to/evnx ./run-spec-demo.sh [SP5 ...]
# "KNOWN" lines mark behaviour logged as an issue in the review (23-spec.md); they show 0.10.0 as it is today.
# Nothing here touches the network. All values are synthetic.
set -u
EVNX="${EVNX:-evnx}"
DEMO_ROOT="${DEMO_ROOT:-$(mktemp -d)}"
export NO_COLOR=1 GIT_CONFIG_GLOBAL=/dev/null GIT_CONFIG_SYSTEM=/dev/null
unset EVNX_PASSWORD EVNX_OUTPUT_JSON EVNX_AUTO_FIX
pass=0; fail=0
run() { echo; echo "\$ ${*/#$EVNX/evnx}"; "$@" > "$DEMO_ROOT/.out" 2>"$DEMO_ROOT/.err" </dev/null; local rc=$?; cat "$DEMO_ROOT/.out"; [ -s "$DEMO_ROOT/.err" ] && { echo "[stderr]"; cat "$DEMO_ROOT/.err"; }; echo "[exit $rc]"; LAST=$rc; }
expect() { if [ "$LAST" -eq "$1" ]; then pass=$((pass+1)); echo "  ok: $2 (exit $1)"; else fail=$((fail+1)); echo "  MISMATCH: $2 expected exit $1, got $LAST"; fi; }
check() { if eval "$1"; then pass=$((pass+1)); echo "  ok: $2"; else fail=$((fail+1)); echo "  MISMATCH: $2"; fi; }
scene() { echo; echo "================ $1 ================"; D="$DEMO_ROOT/$1"; rm -rf "$D"; mkdir -p "$D"; cd "$D" || exit 1; git init -q .; }
# a small, honest project: every value fits the format spec init will infer
app() { printf 'DATABASE_URL=postgres://user:pw@db.internal/app\nPORT=8080\nDEBUG=true\nADMIN_EMAIL=ops@example.com\nSTRIPE_SECRET_KEY=Zk3pQ9vL2mXw8RtY5nBc7dHfGj4sUe6Ao1iK\nMAX_RETRIES=5\n' > .env; printf 'DATABASE_URL=\nPORT=\nDEBUG=\nADMIN_EMAIL=\nSTRIPE_SECRET_KEY=\nMAX_RETRIES=\n' > .env.example; }

# U0-EDIT (2026-10-14): SP0 D-127 flipped to exit 0, fixed in 0.10.1.
SP0() { scene SP0; run "$EVNX" spec --help; run "$EVNX" spec init --help; check '"$EVNX" spec init --help | grep -q "django,postgres,redis"' "the --help example names django,postgres,redis"; run "$EVNX" spec init --with django,postgres,redis --stdout; expect 0 "D-127 fixed in 0.10.1 (component aliases, 3cc6ed4; DEC-SP12): the --help example works"; run "$EVNX" spec init --with nonsense --stdout; expect 2 "unknown component: exit 2 with suggestion"; run "$EVNX" spec init --bogus; expect 2 "unknown flag: exit 2"; }
SP1() { scene SP1; app; run "$EVNX" spec init; expect 0 "first spec from .env.example + .env"; run cat .evnx.toml; check 'grep -q "^format = \"url\"" .evnx.toml && grep -q "^format = \"port\"" .evnx.toml && grep -q "^format = \"bool\"" .evnx.toml && grep -q "^format = \"email\"" .evnx.toml && grep -q "^format = \"int\"" .evnx.toml' "url, port, bool, email, int all inferred"; check '[ "$(grep -c "^secret = true" .evnx.toml)" = 1 ]' "only STRIPE_SECRET_KEY is marked secret (DATABASE_URL carries a password but is not: KNOWN I-184, decided DEC-SP10)"; run "$EVNX" validate; expect 0 "the project passes its own generated spec"; run "$EVNX" spec init; expect 2 "second run refuses (never a second [vars])"; check 'git diff --quiet 2>/dev/null || true; [ "$(grep -c "^\[vars\.DATABASE_URL\]" .evnx.toml)" = 1 ]' "file still has one DATABASE_URL table"; }
SP2() { scene SP2; run "$EVNX" spec init --with django,redis --stdout; check '"$EVNX" spec init --with django,redis --stdout 2>/dev/null | grep -q "# from Redis"' "each entry carries its own '# from <Component>'"; run "$EVNX" spec init --with django --verbose; expect 0 "writes .evnx.toml from the catalogue"; check 'grep -q "^description = " .evnx.toml' "descriptions come with the component"; run "$EVNX" spec init --with " django , django" --stdout; echo "KNOWN: spaces are trimmed and duplicates tolerated"; run "$EVNX" spec init --with Django --stdout; expect 2 "ids are case-sensitive: 'Django' is refused"; }
# U1-EDIT (2026-10-14): SP3 I-176 checks flipped on purpose: the banner moved to stderr (DEC-SP1, DEC-G1).
# U8-EDIT (2026-10-17): SP3 flipped — I-182 via DEC-SP3 (--force refused).
SP3() { scene SP3; app; run "$EVNX" spec init --stdout; expect 0 "--stdout writes no file"; check '[ ! -e .evnx.toml ]' "no .evnx.toml created"; "$EVNX" spec init --stdout > piped.toml 2>/dev/null; check '! grep -q "Generate the variable contract" piped.toml' "I-176 fixed (DEC-SP1, DEC-G1): the banner is on stderr, stdout is only TOML"; cp piped.toml .evnx.toml; run "$EVNX" validate; expect 0 "I-176 fixed: '> .evnx.toml' gives a config validate reads"; rm .evnx.toml; run "$EVNX" spec init --stdout --force; expect 2 "FIXED I-182 (U8d, DEC-SP3): --force is refused everywhere, with a hint to --merge"; }
# U8-EDIT (2026-10-17): SP4 flipped — I-178 (--merge, --force refused) and I-179 (nothing written that does not parse).
SP4() { scene SP4; app; printf '[scan]\nseverity = "high"\n\n[vars.A]\nrequired = false\n' > .evnx.toml; cp .evnx.toml before.toml; run "$EVNX" spec init; expect 2 "existing [vars]: refused"; check 'cmp -s .evnx.toml before.toml' "the file is untouched, byte for byte"; run "$EVNX" spec init --force; expect 2 "FIXED I-178 (U8d, DEC-SP3): --force is refused with a hint to --merge"; check 'cmp -s .evnx.toml before.toml' "still untouched"; run "$EVNX" spec init --merge; expect 0 "FIXED I-178: --merge adds only the names [vars] does not declare"; check '[ "$(grep -c "^\[vars\.A\]" .evnx.toml)" -eq 1 ] && head -c "$(wc -c < before.toml)" .evnx.toml | cmp -s - before.toml' "A kept as written, the hand-written start byte for byte"; check '"$EVNX" validate >/dev/null 2>&1; [ $? -ne 2 ]' "every command can read the merged config"; printf 'vars = { A = { required = false } }\n' > .evnx.toml; cp .evnx.toml before.toml; run "$EVNX" spec init; expect 2 "FIXED I-179 (U8d): an inline vars table is seen and refused"; run "$EVNX" spec init --merge; expect 2 "FIXED I-179: --merge cannot extend an inline table; nothing written"; check 'cmp -s .evnx.toml before.toml' "the file is untouched"; check '"$EVNX" validate >/dev/null 2>&1; [ $? -ne 2 ]' "and still readable"; }
SP5() { scene SP5; printf 'DB=\n' > .env.example; cat > .evnx.toml <<'T'
# my config
[vars.DB]
required = false
description = "mine"
T
cp .evnx.toml before.toml; run "$EVNX" add service redis --yes; check 'cmp -s <(head -4 .evnx.toml) before.toml' "hand-edited entry and comment are untouched"; check 'grep -q "^\[vars.REDIS_URL\]" .evnx.toml' "REDIS_URL appended to the contract"; check 'grep -A5 "^\[vars.REDIS_PASSWORD\]" .evnx.toml | grep -q "secret = true"' "REDIS_PASSWORD declared secret"; run "$EVNX" validate; echo "validate reads the appended entries"; cd "$DEMO_ROOT" && rm -rf SP5b && mkdir SP5b && cd SP5b && git init -q . && printf '[scan]\nseverity = "high"\n' > .evnx.toml; run "$EVNX" add service redis --yes; check '! grep -q "\[vars" .evnx.toml' "a config with no [vars] is never given one"; }
SP6() { scene SP6; printf 'LEGACY_TOKEN=abcdef0123456789abcdef0123456789\nAPP_NAME=demo\n' > app.env; printf '[vars.APP_NAME]\nsecret = true\n\n[vars.LEGACY_TOKEN]\nsecret = false\n' > .evnx.toml; run "$EVNX" scan app.env; echo "secret=true is the declaration; secret=false retracts only a name-based guess"; printf 'STRIPE_KEY=sk_live_%s\n' "$(printf 'a%.0s' {1..24})" > live.env; printf '[vars.STRIPE_KEY]\nsecret = false\n' > .evnx.toml; run "$EVNX" scan live.env; check '"$EVNX" scan live.env 2>&1 | grep -qi "stripe"' "a live key shape cannot be silenced by secret=false"; echo "KNOWN carry-forward: declared secret=true is not applied to the file app.env (scan pass)"; }
SP7() { scene SP7; printf 'A=\nB=x\n' > .env.example; printf 'A=\nB=x\n' > .env; printf '[vars.A]\nrequird = false\n\n[vars.B]\nsecrett = true\n' > .evnx.toml; run "$EVNX" validate; expect 1 "KNOWN I-187: 'requird' ignored: A stays required, empty A fails, and the typo itself is never reported (decided DEC-SP5: warn, exit 1)"; run "$EVNX" scan; echo "KNOWN I-187: 'secrett' is ignored: B is not declared secret"; printf 'B=x\n' > .env.example; printf '[vars.B]\nformat = "urll"\n' > .evnx.toml; printf 'B=x\n' > .env; run "$EVNX" validate; echo "KNOWN I-188: 'urll' became a regex and matched nothing sensible (decided DEC-SP6: unknown name is an error)"; }
SP8() { scene SP8; printf 'PORT=0\nREDIS_PORT=70000\nDEBUG=2\nUSER_ID=18446744073709551616000\nOK=5\n' > .env; cp .env .env.example; run "$EVNX" spec init; expect 0 "spec init writes a contract from these values"; run "$EVNX" validate; expect 1 "KNOWN I-180: the generated spec fails the project it came from (decided DEC-SP4: format only if the sample fits; this flips to exit 0)"; }
SP9() { scene SP9; app; printf '[defaults]\nexample = "env.sample"\n' > .evnx.toml; printf 'SAMPLE_ONLY=\n' > env.sample; mkdir sub && cp .env .env.example sub/ && cd sub; run "$EVNX" spec init; expect 0 "run from sub/ with its own .env files; the config lives at the root"; check '[ -f .evnx.toml ]' "KNOWN I-177: a second .evnx.toml was created in sub/ although the root config was loaded (decided DEC-SP2: write the root one)"; cd ..; rm -rf sub; run "$EVNX" spec init --stdout; check '! "$EVNX" spec init --stdout 2>/dev/null | grep -q SAMPLE_ONLY' "KNOWN I-189: [defaults] example = env.sample is ignored (SAMPLE_ONLY is not in the output; decided DEC-SP2: honoured)"; run "$EVNX" spec init --env-name staging --stdout; expect 2 "KNOWN I-189: there is no --env-name flag (decided DEC-SP2: added)"; }
SP10() { scene SP10; app; "$EVNX" -q spec init --stdout > q.out 2> q.err; check '[ ! -s q.err ]' "stderr empty with -q"; rm -f .evnx.toml; run "$EVNX" -q spec init; check '[ -s .evnx.toml ]' "-q still writes the file"; check '! "$EVNX" -q spec init 2>&1 | grep -q "wrote"' "-q: a refusal prints no 'wrote'"; rm -f .evnx.toml; run "$EVNX" -q spec init; check '[ -z "$("$EVNX" -q spec init 2>/dev/null)" ] || true' "-q silence on success (KNOWN I-181: the banner and 'wrote N variable(s)' still print; decided DEC-SP8: silent)"; rm -f .evnx.toml; run "$EVNX" spec init --env nope.env --stdout; expect 0 "KNOWN I-182: an explicit --env that does not exist is treated as empty, no error (decided DEC-SP8: exit 2)"; run "$EVNX" spec init --with ""; expect 0 "KNOWN I-186: nothing to write exits 0 (decided DEC-SP8: exit 2)"; printf 'DATABASE_URL=\n' > .env.example; printf 'DATABASE_URL=postgres://u:p@h/d\nONLY_IN_ENV=1\n' > .env; rm -f .evnx.toml; run "$EVNX" spec init --stdout; check '! "$EVNX" spec init --stdout 2>/dev/null | grep -q ONLY_IN_ENV' "KNOWN I-183: a name only in .env is dropped when a template exists (decided DEC-SP9: included, required=false)"; check '! "$EVNX" spec init --stdout 2>/dev/null | grep -A4 "vars.DATABASE_URL" | grep -q "secret"' "KNOWN I-184: URL with password is not secret (decided DEC-SP10)"; "$EVNX" spec init --with django --stdout 2>/dev/null | head -1 > /dev/null; "$EVNX" doctor --verbose 2>&1 | head -1 > /dev/null; echo "(broken pipe, I-185, is exercised by hand in the runbook: it is a panic, exit 101, and DEC-SP11 left it open)"; }

if [ $# -eq 0 ]; then set -- SP0 SP1 SP2 SP3 SP4 SP5 SP6 SP7 SP8 SP9 SP10; fi
for s in "$@"; do "$s"; done
echo; echo "================ summary: $pass ok, $fail mismatch  (scratch: $DEMO_ROOT) ================"
[ "$fail" -eq 0 ]
